* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
}

.login-page {
  display: grid;
  grid-template-columns: 1fr 0.94fr;
  min-height: 100svh;
  padding: var(--g-spacing-4);
  background: var(--g-color-base-background);
  color: var(--g-color-text-primary);
}

.login-side {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: var(--g-spacing-8) calc(var(--g-spacing-10) + var(--g-spacing-2));
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--g-spacing-3);
  width: fit-content;
}

.brand-name {
  font-family: var(--g-font-family-sans);
  font-size: 30px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: -1.4px;
}

.brand-period {
  color: var(--g-color-text-secondary);
}

.brand-mark-accent {
