}

.planet-mid {
  stop-color: var(--g-color-base-brand);
}

.planet-dark {
  stop-color: var(--g-color-text-warning-heavy);
}

.orbit-dot {
  fill: var(--g-color-text-primary);
}

.orbit-small-dot {
  fill: var(--g-color-base-brand);
}

.orbit-spark {
  stroke: var(--g-color-text-primary);
  stroke-width: 1.5;
}

.welcome-copy {
  padding-left: var(--g-spacing-2);
  margin-top: var(--g-spacing-3);
