  font-size: var(--g-text-caption-1-font-size);
  letter-spacing: 1px;
}

.slide-markers {
  display: flex;
  gap: var(--g-spacing-1);
  flex-shrink: 0;
}

.slide-markers i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--g-color-line-generic);
}

.slide-markers i:first-child {
  width: 18px;
  border-radius: var(--g-border-radius-s);
  background: var(--g-color-text-primary);
}

@media (min-width: 1600px) {
  .login-side {
    padding-left: calc(var(--g-spacing-10) * 2);
    padding-right: calc(var(--g-spacing-10) * 2);
  }
  .welcome-side {
    padding-left: calc(var(--g-spacing-10) * 2);
    padding-right: calc(var(--g-spacing-10) * 2);
  }
}

@media (max-width: 1000px) {
